#!/usr/bin/env Rscript
# Conclusion: UPR ordinal responses transfer in untreated external contexts, with
# retained composition sensitivity and no multiplicity-supported transfer in IFNg/co-culture.
# Evidence: all-gene UPR scatters -> full48 exploratory family -> four-context composition control.
# Quantitative grid,183x156mm,R-only editable vector output and native QA preview.
suppressPackageStartupMessages({library(data.table);library(ggplot2);library(patchwork);library(ggrepel)})
a<-commandArgs(TRUE);ff<-grep('^--file=',commandArgs(FALSE),value=TRUE);here<-dirname(normalizePath(sub('^--file=','',ff)));work<-if(length(a))normalizePath(a[1])else here;final<-if(length(a)>1)a[2]else file.path(work,'Fig_UPR_external_validation.pdf')
theme_set(theme_classic(base_size=7,base_family='Helvetica')+theme(axis.line=element_line(linewidth=.35),axis.ticks=element_line(linewidth=.35),axis.text=element_text(size=6.3),axis.title=element_text(size=7),legend.title=element_text(size=6.2),legend.text=element_text(size=6),plot.title=element_text(size=7),plot.tag=element_text(size=8,face='bold'),plot.margin=margin(5,6,4,5),panel.grid=element_blank()))
upr<-'hallmark_UNFOLDED_PROTEIN_RESPONSE';co<-fread(file.path(work,'exploratory_axis_conservation.tsv'));g<-fread(file.path(work,'exploratory_all_gene_axis_effects.tsv.gz'))[axis==upr];exact<-fread(file.path(work,'UPR_exact_composition_correlation_sensitivity.tsv'))
scatter<-function(st,ctx,title){
 d<-g[study==st&context==ctx];dd<-copy(d);dd[,extreme:=pmax(abs(discovery_effect),abs(external_effect))];setorder(dd,-extreme,gene);lab<-dd[1:6,gene];d[,label:=fifelse(gene%in%lab,gene,'')]
 stat<-co[study==st&context==ctx&axis==upr];ann<-sprintf('Spearman rho = %.2f [%.2f, %.2f]\nBH q (48 tests) = %.4f',stat$spearman,stat$conditional_gene_bootstrap_low,stat$conditional_gene_bootstrap_high,stat$BH_q_all_48)
 ggplot(d,aes(discovery_effect,external_effect))+geom_hline(yintercept=0,linetype=2,colour='#A5A5A5',linewidth=.3)+geom_vline(xintercept=0,linetype=2,colour='#A5A5A5',linewidth=.3)+geom_point(size=1.8,colour='#4C78A8',alpha=.9)+geom_text_repel(aes(label=label),seed=20261106,size=2.15,max.overlaps=Inf,box.padding=.25,point.padding=.2,min.segment.length=0,segment.size=.2,colour='#303030')+annotate('text',x=-Inf,y=Inf,label=ann,hjust=-.04,vjust=1.15,size=2.25,lineheight=1.15)+scale_x_continuous(expand=expansion(mult=c(.08,.14)))+scale_y_continuous(expand=expansion(mult=c(.05,.24)))+labs(x='Source K562 UPR shift (control SD)',y='External UPR shift (control SD)',title=title)
}
pA<-scatter('Adamson2016','Adamson_K562_UPR','Independent K562 study (30 genes)')
pB<-scatter('Frangieh2021','Control','Melanoma, untreated context (19 genes)')
axis_order<-c('apoptosis','proliferation','stress',upr,'hallmark_E2F_TARGETS','hallmark_G2M_CHECKPOINT','hallmark_P53_PATHWAY','hallmark_TNFA_SIGNALING_VIA_NFKB','hallmark_INTERFERON_GAMMA_RESPONSE','hallmark_MTORC1_SIGNALING','hallmark_OXIDATIVE_PHOSPHORYLATION','hallmark_HYPOXIA')
axis_labels<-c('Apoptosis','Proliferation','Stress','UPR','E2F targets','G2M checkpoint','p53 pathway','TNF / NFkB','IFNg response','mTORC1','OXPHOS','Hypoxia')
cohort<-function(st,ctx)fifelse(st=='Adamson2016','K562\nAdamson',fifelse(ctx=='Control','Melanoma\nuntreated',fifelse(ctx=='IFNγ','Melanoma\nIFNg','Melanoma\nco-culture')))
co[,readout:=factor(axis,levels=rev(axis_order))];co[,cohort:=factor(cohort(study,context),levels=c('K562\nAdamson','Melanoma\nuntreated','Melanoma\nIFNg','Melanoma\nco-culture'))];co[,label:=paste0(sprintf('%.2f',spearman),fifelse(BH_q_all_48<.05,'*',''))]
pC<-ggplot(co,aes(cohort,readout,fill=spearman))+geom_tile(colour='white',linewidth=.4)+geom_text(aes(label=label),size=1.9)+scale_fill_gradient2(low='#D9A16B',mid='white',high='#4C78A8',midpoint=0,limits=c(-1,1),breaks=c(-1,0,1))+scale_y_discrete(labels=setNames(axis_labels,axis_order))+labs(x=NULL,y=NULL,fill='Spearman rho',title='Complete exploratory family: 12 axes x 4 contexts',caption='*BH q < 0.05 across all 48 tests.')+theme(axis.line=element_blank(),axis.ticks=element_blank(),axis.text.y=element_text(size=6),axis.text.x=element_text(size=5.7),legend.position='bottom',legend.key.width=grid::unit(5,'mm'),legend.key.height=grid::unit(2,'mm'),plot.caption=element_text(size=6,hjust=0))
orig<-co[axis==upr,.(study,context,genes,spearman,low=conditional_gene_bootstrap_low,high=conditional_gene_bootstrap_high,method='Original matched-gene score',q=BH_q_all_48)]
ee<-exact[,.(study,context,genes,spearman,low=conditional_gene_bootstrap_low,high=conditional_gene_bootstrap_high,method='Exact own-target exclusion',q=BH_q_sensitivity_all48)]
f<-rbind(orig,ee);f[,cohort:=fifelse(study=='Adamson2016','K562 / Adamson (30)',fifelse(context=='Control','Melanoma / untreated (19)',fifelse(context=='IFNγ','Melanoma / IFNg (19)','Melanoma / co-culture (17)')))];f[,cohort:=factor(cohort,levels=rev(c('K562 / Adamson (30)','Melanoma / untreated (19)','Melanoma / IFNg (19)','Melanoma / co-culture (17)')))];f[,method:=factor(method,levels=c('Original matched-gene score','Exact own-target exclusion'))]
pD<-ggplot(f,aes(spearman,cohort,colour=method,shape=method))+geom_vline(xintercept=0,linetype=2,colour='#999999',linewidth=.3)+geom_errorbar(aes(xmin=low,xmax=high),orientation='y',position=position_dodge(width=.42),width=.12,linewidth=.4)+geom_point(size=1.9,position=position_dodge(width=.42))+scale_colour_manual(values=c('#4C78A8','#525252'))+scale_shape_manual(values=c(16,17))+scale_x_continuous(limits=c(-1,1),breaks=c(-1,-.5,0,.5,1))+labs(x='UPR response Spearman correlation',y=NULL,colour=NULL,shape=NULL,title='Own-target numerator and denominator control',caption='Intervals: 95% bootstrap over assayed genes.\nExact exclusion rescored treated and matched control cells.')+theme(axis.text.y=element_text(size=6),legend.position='bottom',legend.box='vertical',plot.caption=element_text(size=6,hjust=0))+guides(colour=guide_legend(nrow=2,byrow=TRUE),shape=guide_legend(nrow=2,byrow=TRUE))
fig<-pA+pB+pC+pD+plot_layout(design='AB\nCD',widths=c(1,1.1),heights=c(1,1.18))+plot_annotation(tag_levels='a')&theme(plot.tag=element_text(size=8,face='bold'))
dir.create(dirname(final),recursive=TRUE,showWarnings=FALSE)
if(Sys.info()[['sysname']]=='Darwin')quartz(type='pdf',file=final,width=183/25.4,height=156/25.4,family='Helvetica')else cairo_pdf(final,width=183/25.4,height=156/25.4,family='Helvetica');print(fig);dev.off()
svglite::svglite(file.path(work,'Fig_UPR_external_validation.svg'),width=183/25.4,height=156/25.4);print(fig);dev.off()
ragg::agg_png(file.path(work,'Fig_UPR_external_validation_preview.png'),width=183,height=156,units='mm',res=180);print(fig);dev.off()
fwrite(g,file.path(work,'Fig_UPR_external_validation_scatter_source.tsv'),sep='\t');fwrite(co,file.path(work,'Fig_UPR_external_validation_all48_source.tsv'),sep='\t');fwrite(f,file.path(work,'Fig_UPR_external_validation_composition_source.tsv'),sep='\t')
writeLines(c('UPR response ordering across independent perturbation studies. a,b, Source Replogle K562 and independent Adamson K562 (a; 30 genes) or untreated Frangieh melanoma (b; 19 genes) UPR shifts, standardized to the respective non-targeting-control standard deviation. Every eligible gene is shown; labels identify the six largest absolute effects in either context. Dashed lines mark zero. Spearman correlations are accompanied by 95% intervals from 2,000 whole-gene bootstrap draws and BH-adjusted q values from 10,000 two-sided whole-gene permutations across the full 48-test family. c, All 12 prespecified molecular readouts in four external contexts: Adamson K562 (30 genes), untreated melanoma (19), IFNg-treated melanoma (19), and melanoma co-culture (17). Asterisks indicate BH q<0.05 across all 48 tests. d, UPR correlations before and after exact removal of the perturbed gene from the UPR numerator when present and from the 7,848-gene normalization denominator when measured, rescoring treated and matched non-targeting cells and recomputing target-specific control standard deviations. Error bars are 95% whole-gene bootstrap intervals; original and corrected estimates are paired within each context. The corrected four UPR tests replace the original four UPR tests in a separate 48-test sensitivity family. These analyses examine ordinal program responses after the original aggregate priority failed external validation. The UPR follow-up is exploratory, and does not establish cross-context amplitude equivalence, a mechanism, biological replication, or a difference between external contexts. Source Data are provided in the accompanying scatter, all-48-association and composition-sensitivity tables.'),file.path(work,'Fig_UPR_external_validation_legend.txt'))
print(pdftools::pdf_fonts(final));pdftools::pdf_convert(final,format='png',dpi=150,filenames=file.path(work,'Fig_UPR_external_validation_pdf_QA.png'),verbose=FALSE)
